import { PutItemCommand } from 'dynamodb-toolbox/entity/actions/put';
import { ScanCommand } from 'dynamodb-toolbox/table/actions/scan';
import { MODELO_DOCUMENTO, MODELO_ARCHIVO, TABLA_DOCUMENTOS } from '../../models/archivo-documento.model.mjs';

export async function crearDocumentoRepository(documento) {
  await MODELO_DOCUMENTO.build(PutItemCommand)
    .item(documento)
    .options({ condition: { attr: 'documentoId', exists: false } })
    .send();
}

export async function listarDocumentosRepository() {
  const { Items = [] } = await TABLA_DOCUMENTOS.build(ScanCommand)
    .entities(MODELO_DOCUMENTO)
    .options({ consistent: true })
    .send();
  return Items;
}

