import { UpdateItemCommand } from 'dynamodb-toolbox/entity/actions/update';
import { MODELO_DOCUMENTO, MODELO_ARCHIVO, TABLA_DOCUMENTOS } from '../../models/archivo-documento.model.mjs';

export async function trasladarDocumentoRepository(documentoId, archivoId) {
  const { Attributes } = await MODELO_DOCUMENTO.build(UpdateItemCommand)
    .item({ documentoId, archivoId })
    .options({
      condition: { attr: 'documentoId', exists: true },
      returnValues: 'ALL_NEW'
    })
    .send();
  return Attributes;
}

import { consultarArchivoService } from './service.mjs';

export async function handler(event) {
  const archivoId = Number(event.pathParameters.archivoId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarArchivoService(archivoId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarArchivoRepository, consultarArchivoRepository } from './repository.mjs';

export async function consultarArchivoService(archivoId, minimo) {
  const archivo = await buscarArchivoRepository(archivoId);
  if (!archivo) throw new Error('Archivo no encontrado');
  const documentos = await consultarArchivoRepository(archivoId, minimo);
  return { archivo, documentos };
}

import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_DOCUMENTO, MODELO_ARCHIVO, TABLA_DOCUMENTOS } from '../../models/archivo-documento.model.mjs';

export async function buscarArchivoRepository(archivoId) {
  const { Item } = await MODELO_ARCHIVO.build(GetItemCommand)
    .key({ archivoId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarArchivoRepository(archivoId, minimo) {
  const { Items = [] } = await TABLA_DOCUMENTOS.build(QueryCommand)
    .entities(MODELO_DOCUMENTO)
    .query({ index: 'PorArchivo', partition: archivoId })
    .options({ filters: { Documento: { attr: 'paginas', gte: minimo } } })
    .send();
  return Items;
}
